#include <vector>
#include <algorithm>
#include <unordered_map>

class Solution {
    std::unordered_map<int, int> cache;
    int getPower(int x) {
        if (x == 1) return 0;
        if (cache.count(x)) return cache[x];
        int res = 1 + (x % 2 == 0 ? getPower(x / 2) : getPower(3 * x + 1));
        return cache[x] = res;
    }
public:
    int getKth(int lo, int hi, int k) {
        std::vector<std::pair<int, int>> items;
        for (int i = lo; i <= hi; ++i) {
            items.push_back({getPower(i), i});
        }
        std::sort(items.begin(), items.end());
        return items[k - 1].second;
    }
};

import java.util.*;

class Solution {
    private Map<Integer, Integer> cache = new HashMap<>();
    private int getPower(int x) {
        if (x == 1) return 0;
        if (cache.containsKey(x)) return cache.get(x);
        int res = 1 + (x % 2 == 0 ? getPower(x / 2) : getPower(3 * x + 1));
        cache.put(x, res);
        return res;
    }
    public int getKth(int lo, int hi, int k) {
        List<int[]> items = new ArrayList<>();
        for (int i = lo; i <= hi; i++) {
            items.add(new int[]{getPower(i), i});
        }
        items.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        return items.get(k - 1)[1];
    }
}

var getKth = function(lo, hi, k) {
    const cache = new Map();
    cache.set(1, 0);
    const getPower = (x) => {
        if (cache.has(x)) return cache.get(x);
        const res = 1 + (x % 2 === 0 ? getPower(Math.floor(x / 2)) : getPower(3 * x + 1));
        cache.set(x, res);
        return res;
    };
    const items = [];
    for (let i = lo; i <= hi; i++) {
        items.push([getPower(i), i]);
    }
    items.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
    return items[k - 1][1];
};
